+
+	node = cache_node;
+	if (node) {
+		node->connect("draw", callable_mp(this, &ScenePaintEditor::_draw));
+	}
+	_update_draw();
+	callable_mp(this, &ScenePaintEditor::_update_preview).call_deferred();
