+void ScenePaintEditor::_scene_changed() {
+	is_painting = false;
+	is_erasing = false;
+	Node *scene = EditorNode::get_singleton()->get_edited_scene();
+	if (pinned_nodes.has(scene)) {
+		pinned = true;
+		pin_node_button->set_pressed_no_signal(true);
+		cache_node = Object::cast_to<Node2D>(pinned_nodes[scene]);
+	} else {
+		pinned = false;
+		pin_node_button->set_pressed_no_signal(false);
+		cache_node = Object::cast_to<Node2D>(Object::cast_to<Node>(EditorNode::get_singleton()->get_editor_selection()->get_selected_nodes().pop_front()));
+	}
+	_update_node();
+}
