+		preview = nullptr;
+		instance = nullptr;
+	}
+	bool success = false;
+	String scene_path;
+	Node2D *node_2d = nullptr;
+	switch (p_mode) {
+		case PICK_FILE_SYSTEM: {
+			scene_path = FileSystemDock::get_singleton()->get_current_path();
+			Ref<PackedScene> scene = ResourceLoader::load(scene_path);
+			if (scene.is_valid()) {
