+void ScenePaintEditor::set_grid_step(const Size2i p_size) {
+	grid_step = p_size;
+	EditorSettings::get_singleton()->set_project_metadata("scene_paint_editor", "grid_step", grid_step);
+	_update_grid_step();
+}
