+	cache_node = Object::cast_to<Node2D>(p_object);
+	if (node && (pinned || scene_picker)) {
+		if (scene_picker) {
+			SceneTreeDock::get_singleton()->set_selection(Vector<Node *>{ node });
+		}
+		return;
+	}
