+void ScenePaintEditor::_can_handle(bool p_is_node_2d, bool p_edit) {
+	if ((p_is_node_2d || pinned) && is_tool_selected && node) {
+		toolbar->show();
+	} else {
+		toolbar->hide();
+		if (p_edit) {
+			_edit(nullptr);
