+	TileMapLayer *edited_layer = Object::cast_to<TileMapLayer>(p_object);
+	if (edited_layer) {
+		Ref<TileSet> tile_set = edited_layer->get_tile_set();
+		if (tile_set.is_valid()) {
+			set_grid_step(tile_set->get_tile_size());
+		}
+	}
