+		if (instance) {
+			instance->queue_free();
+			instance = nullptr;
+		}
+		if (preview && preview->get_parent() != node) {
+			preview->reparent(node);
+		}
+		if (!preview) {
+			preview = memnew(Node2D);
+			preview->set_modulate(Color(1, 1, 1, 0.5));
+			node->add_child(preview);
+		}
+	}
+	if (preview) {
+		if (selected_scene.is_valid()) {
