+		return;
+	}
+
+	Vector2 cell_pos = _get_mouse_grid_cell();
+	Vector2 pos = canvas_xform.affine_inverse().xform(mouse_pos);
+
+	if (grid) {
+		pos = snap_grid ? cell_pos : (cell_pos + get_grid_step() / 2.0);
+	} else {
+		pos = (pos - node->get_global_position()).round();
