+	} else {
+		pos = (pos - node->get_global_position()).round();
+	}
+
+	Node *parent = EditorNode::get_singleton()->get_edited_scene();
+	TypedArray<Node> children = parent->find_children("*", "Node2D");
+	for (int i = 0; i < children.size(); i++) {
