+	String name = "new_folder";
+	int counter = 0;
+	while (palette->has_folder(name)) {
+		counter++;
+		name = vformat("new_folder_%d", counter);
+	}
+	item->set_text(0, name);
+	item->set_metadata(0, name);
+	item->set_editable(0, true);
+	palette->add_folder(name);
