+bool ScenePaintEditor::_add_scene_request(const String &p_path) {
+	Ref<PackedScene> scene = ResourceLoader::load(p_path);
+	if (scene.is_valid()) {
+		// Check if it extends CanvasItem.
+		Ref<SceneState> scene_state = scene->get_state();
+		String type;
+		while (scene_state.is_valid() && type.is_empty()) {
+			// Make sure we have a root node. Supposed to be at 0 index because find_node_by_path() does not seem to work.
+			ERR_FAIL_COND_V(scene_state->get_node_count() < 1, false);
+
+			type = scene_state->get_node_type(0);
+			scene_state = scene_state->get_base_scene_state();
+		}
+		ERR_FAIL_COND_V_EDMSG(type.is_empty(), false, vformat("Invalid PackedScene for ScenePaint: %s. Could not get the type of the root node.", scene->get_path()));
+		bool extends_correct_class = ClassDB::is_parent_class(type, "Node2D");
+		ERR_FAIL_COND_V_EDMSG(!extends_correct_class, false, vformat("Invalid PackedScene for ScenePaint: %s. Root node should extend Node2D. Found %s instead.", scene->get_path(), type));
+		String display_name = p_path.get_file().get_basename();
+		palette->add_scene(edited_folder, p_path, display_name, palette->get_grid_step(edited_folder));
+		_update_scene_list();
+		_update_toolbar_buttons();
+		return true;
+	}
+	return false;
+}
+
+void ScenePaintEditor::_update_scene_list() {
+	selected_scene_index = -1;
+	item_list->clear();
+	const ScenePalette::FolderData &folder = palette->get_folder(edited_folder);
+
+	for (const ScenePalette::SceneData &E : folder.scenes) {
+		int udata = item_list->add_item(E.display_name);
+		Ref<PackedScene> scene = ResourceLoader::load(E.scene_path);
+		EditorResourcePreview::get_singleton()->queue_edited_resource_preview(scene, this, "_scene_thumbnail_done", udata);
+	}
+}
