+
+	CanvasItemEditor *canvas = CanvasItemEditor::get_singleton();
+	Vector2 mouse_canvas = canvas->get_viewport_control()->get_local_mouse_position();
+	Vector2 mouse_world = canvas->get_canvas_transform().affine_inverse().xform(mouse_canvas);
+
+	if (grid || snap_grid) {
+		Vector2 cell_pos = _get_mouse_grid_cell() - node->get_global_position();
+		mouse_world = snap_grid ? cell_pos : (cell_pos + get_grid_step() / 2.0);
+	}
+	Vector<CanvasItemEditor::_SelectResult> results;
+	canvas->get_canvas_items_at_pos(mouse_world, results);
+
+	for (int i = 0; i < results.size(); i++) {
+		Node2D *node_2d = Object::cast_to<Node2D>(results[i].item);
+		if (!node_2d || !node_2d->has_meta("_scene_painted")) {
+			continue;
+		}
+		node_2d->queue_free();
+	}
