+void ScenePaintEditor::_gui_input_viewport(const Ref<InputEvent> &p_event) {
+	if (!is_visible_in_tree() || !is_tool_selected) {
+		return;
+	}
+
+	CanvasItemEditor *canvas = CanvasItemEditor::get_singleton();
+	Transform2D canvas_xform = canvas->get_canvas_transform();
+
+	Ref<InputEventMouseButton> mb = p_event;
+
+	if (mb.is_valid()) {
+		is_painting = mb->is_pressed() && mb->get_button_index() == MouseButton::LEFT;
+		is_erasing = mb->is_pressed() && mb->get_button_index() == MouseButton::RIGHT;
+		if (is_painting && !is_erasing && !scene_picker) {
+			_add_node_at_pos(mb->get_position(), canvas_xform);
+			accept_event();
+		}
+		if (is_erasing && !is_painting && !scene_picker) {
+			_remove_node_at_pos(mb->get_position(), canvas_xform);
+			accept_event();
+		}
+		if (!is_painting) {
+			last_paint_pos = Vector2();
+		}
+		if (is_painting && scene_picker) {
+			_update_scene_picker(PICK_CANVAS_ITEM);
+		}
+	}
+
+	Ref<InputEventMouseMotion> mm = p_event;
+
+	if (mm.is_valid()) {
+		_update_paint_rect(mm->get_position(), canvas_xform);
+		_update_preview_position(mm->get_position(), canvas_xform);
+
+		if (is_painting && !is_erasing && !scene_picker) {
+			_add_node_at_pos(mm->get_position(), canvas_xform);
+			accept_event();
+		}
+		if (is_erasing && !is_painting && !scene_picker) {
+			_remove_node_at_pos(mm->get_position(), canvas_xform);
+			accept_event();
+		}
+	}
+	_update_draw();
+}
+
+void ScenePaintEditor::_add_node_at_pos(const Vector2 &mouse_pos, const Transform2D &canvas_xform) {
+	if (!node) {
+		return;
+	}
+
+	Vector2 cell_pos = _get_mouse_grid_cell() - node->get_global_position();
+	Vector2 pos = canvas_xform.affine_inverse().xform(mouse_pos);
+
+	if (grid || snap_grid) {
+		pos = snap_grid ? cell_pos : (cell_pos + get_grid_step() / 2.0);
+	}
+
+	if (last_paint_pos == pos) {
+		return;
+	}
+	last_paint_pos = pos;
+
+	Node2D *node_2d = Object::cast_to<Node2D>(instance->duplicate());
+	if (!node_2d) {
+		return;
+	}
+
+	Node *parent = EditorNode::get_singleton()->get_edited_scene();
+	if (parent) {
+		node->add_child(node_2d, true);
+		node_2d->set_owner(parent);
+		node_2d->set_meta("_scene_painted", true);
+		node_2d->set_global_position(pos);
+	}
+}
+
+void ScenePaintEditor::_remove_node_at_pos(const Vector2 &mouse_pos, const Transform2D &canvas_xform) {
+	if (!node) {
+		return;
+	}
+
+	CanvasItemEditor *canvas = CanvasItemEditor::get_singleton();
+	Vector2 mouse_canvas = canvas->get_viewport_control()->get_local_mouse_position();
+	Vector2 mouse_world = canvas->get_canvas_transform().affine_inverse().xform(mouse_canvas);
+
+	if (grid || snap_grid) {
+		Vector2 cell_pos = _get_mouse_grid_cell() - node->get_global_position();
+		mouse_world = snap_grid ? cell_pos : (cell_pos + get_grid_step() / 2.0);
+	}
+	Vector<CanvasItemEditor::_SelectResult> results;
+	canvas->get_canvas_items_at_pos(mouse_world, results);
+
+	for (int i = 0; i < results.size(); i++) {
+		Node2D *node_2d = Object::cast_to<Node2D>(results[i].item);
+		if (!node_2d || !node_2d->has_meta("_scene_painted")) {
+			continue;
+		}
+		node_2d->queue_free();
+	}
+}
+
+Vector2 ScenePaintEditor::_get_mouse_grid_cell() {
+	if (!node) {
+		return Vector2();
+	}
+
+	CanvasItemEditor *canvas = CanvasItemEditor::get_singleton();
+	Transform2D viewport_to_world = canvas->get_canvas_transform().affine_inverse();
+	Vector2 mouse_canvas = canvas->get_viewport_control()->get_local_mouse_position();
+	Vector2 mouse_world = viewport_to_world.xform(mouse_canvas);
+	Size2i step = get_grid_step();
+	Vector2 origin = node->get_global_position();
+	Vector2 local = mouse_world - origin;
+	Vector2 snapped = Vector2(
+			Math::floor(local.x / step.x) * step.x,
+			Math::floor(local.y / step.y) * step.y);
+
+	return snapped + origin;
+}
