+					accept_event();
+				}
+			} else if (mb->is_released()) {
+				if (mb->get_button_index() == MouseButton::LEFT) {
+					is_painting = false;
+					undo_redo->commit_action(false);
+				} else if (mb->get_button_index() == MouseButton::RIGHT) {
+					is_erasing = false;
+					undo_redo->commit_action(false);
+				}
+			}
+		}
+	}
+
+	Ref<InputEventMouseMotion> mm = p_event;
