+Node2D *ScenePaint2DEditor::_get_node_root(Node *p_node) const {
+	Node *scene = EditorNode::get_singleton()->get_edited_scene();
+	Node2D *item = Object::cast_to<Node2D>(p_node);
+	if (!item) {
+		return nullptr;
