+
+void ScenePaint2DEditor::_add_to_recent_scenes(const String &p_scene) {
+	if (p_scene.is_empty()) {
+		return;
+	}
+	Array rc = EditorSettings::get_singleton()->get_project_metadata("scene_paint_2d_editor", "recent_scenes", Array());
+	if (rc.has(p_scene)) {
+		rc.erase(p_scene);
+	}
+	rc.push_front(p_scene);

