+		pinned_nodes[scene] = node;
+		_update_node();
+	} else {
+		pinned_nodes.erase(scene);
+		Node *selected_node = SceneTreeDock::get_singleton()->get_tree_editor()->get_selected();
+		_update_node(selected_node);
