+			}
+		} break;
+		case PICK_RECENT_LIST: {
+			int index = recent_scenes_popup->get_pressed_id();
+			String scene_path = recent_scenes_popup->get_item_tooltip(index);
+			if (!FileAccess::exists(scene_path)) {
