+						TTR("The selected scene could not be found. It may have been moved or deleted."),
+						TTR("OK"));
+				Array recent_scenes_array = EditorSettings::get_singleton()->get_project_metadata("scene_paint_2d_editor", "recent_scenes", Array());
+				recent_scenes_array.erase(scene_path);
