+				return;
+			}
+			Ref<PackedScene> scene = ResourceLoader::load(scene_path);
+			if (scene.is_valid()) {
+				node_2d = Object::cast_to<Node2D>(scene->instantiate());
+			}
+		}
+	}
+
+	if (_is_selected_scene_valid(node_2d)) {
+		_set_picked_scene(node_2d);
+	}
+}
