+	String tooltip_text = TTR("Pin the current node.\nWhen enabled, the painting parent node won't change when selecting other nodes in the scene.");
+	if (pinned && p_pinned_node) {
+		tooltip_text += TTR(vformat("\nPinned Node: %s", EditorNode::get_singleton()->get_edited_scene()->get_path_to(p_pinned_node)));
